// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNum, uint48 warpedTime) public {
        blockNum = bound(blockNum, 1, 1_000_000);
        vm.assume(warpedTime > 0);
        vm.warp(warpedTime);
        vm.roll(blockNum);

        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback reverted unexpectedly");

        bool divisibleBy15 = (blockNum % 15 == 0);
        bool balanceIsZero = (address(c).balance == 0);
        assertTrue(divisibleBy15 ? balanceIsZero : !balanceIsZero);
    }
}
